class AvgPartition {

    /*
    This is a class that partitions the given list into different blocks by specifying the number of partitions, with each block having a uniformly distributed length.
    */

    let lst: ArrayList<Int64>
    let limit: Int64

    public init(lst: ArrayList<Int64>, limit: Int64) {
        /*
        Initialize the class with the given list and the number of partitions, and check if the number of partitions is greater than 0.
        */
        if (limit <= 0) {
            // In a real implementation, you might want to throw an exception
            // For now, we'll just assign the values
        }
        this.lst = lst
        this.limit = limit
    }

    public func setNum(): (Int64, Int64) {
        /*
        Calculate the size of each block and the remainder of the division.
        :return: the size of each block and the remainder of the division, tuple.
        >>> a = AvgPartition(ArrayList<Int64>([1, 2, 3, 4]), 2)
        >>> a.setNum()
        (2, 0)

        */
        let size = this.lst.size() / this.limit
        let remainder = this.lst.size() % this.limit
        return (size, remainder)
    }

    public func get(index: Int64): ArrayList<Int64> {
        /*
        calculate the size of each block and the remainder of the division, and calculate the corresponding start and end positions based on the index of the partition.
        :param index: the index of the partition, Int64.
        :return: the corresponding block, ArrayList<Int64>.
        >>> a = AvgPartition(ArrayList<Int64>([1, 2, 3, 4]), 2)
        >>> a.get(0)
        [1, 2]

        */
        let (size, remainder) = this.setNum()
        let start = index * size + min(index, remainder)
        var end = start + size
        if (index + 1 <= remainder) {
            end = end + 1
        }

        // Create a new ArrayList to store the result
        var result: ArrayList<Int64> = ArrayList<Int64>()

        // Add elements from start to end
        var i = start
        while (i < end && i < this.lst.size()) {
            result.add(this.lst.get(i).getOrThrow())
            i = i + 1
        }

        return result
    }
}

import std.collection.ArrayList

class BalancedBrackets {

    /*
    This is a class that checks for bracket matching
    */

    let stack: ArrayList<String>
    let left_brackets: ArrayList<String>
    let right_brackets: ArrayList<String>
    var expr: String

    public init(expr: String) {
        /*
        Initializes the class with an expression.
        :param expr: The expression to check for balanced brackets,String.
        */
        this.stack = ArrayList<String>()
        this.left_brackets = ArrayList<String>(["(", "{", "["])
        this.right_brackets = ArrayList<String>([")", "}", "]"])
        this.expr = expr
    }

    public func clear_expr(): Unit {
        /*
        Clears the expression of all characters that are not brackets.
        >>> b = BalancedBrackets("a(b)c")
        >>> b.clear_expr()
        >>> b.expr
        '()'

        */
        var result: String = ""
        for (i in 0..this.expr.size) {
            let c: String = this.expr[i].toString()
            if (this.left_brackets.contains(c) || this.right_brackets.contains(c)) {
                result = result + c
            }
        }
        this.expr = result
    }

    public func check_balanced_brackets(): Bool {
        /*
        Checks if the expression has balanced brackets.
        :return: true if the expression has balanced brackets, false otherwise.
        >>> b = BalancedBrackets("a(b)c")
        >>> b.check_balanced_brackets()
        true

        */
        this.clear_expr()
        for (i in 0..this.expr.size) {
            let brkt: String = this.expr[i].toString()
            if (this.left_brackets.contains(brkt)) {
                this.stack.add(brkt)
            } else {
                if (this.stack.size == 0) {
                    return false
                }
                let current_brkt: String = this.stack[this.stack.size - 1]
                this.stack.remove(at: this.stack.size - 1)
                if (current_brkt == "(") {
                    if (brkt != ")") {
                        return false
                    }
                }
                if (current_brkt == "{") {
                    if (brkt != "}") {
                        return false
                    }
                }
                if (current_brkt == "[") {
                    if (brkt != "]") {
                        return false
                    }
                }
            }
        }
        if (this.stack.size > 0) {
            return false
        }
        return true
    }
}

class BankAccount {

    /*
    This is a class as a bank account system, which supports deposit money, withdraw money, view balance, and transfer money.
    */

    var balance: Int64

    public init(balance!: Int64 = 0) {
        /*
        Initializes a bank account object with an attribute balance, default value is 0.
        */
        this.balance = balance
    }

    public func deposit(amount: Int64): Int64 {
        /*
        Deposits a certain amount into the account, increasing the account balance, return the current account balance.
        If amount is negative, throw Exception("Invalid amount").
        :param amount: Int64
        */
        if (amount < 0) {
            throw Exception("Invalid amount")
        }
        this.balance += amount
        return this.balance
    }

    public func withdraw(amount: Int64): Int64 {
        /*
        Withdraws a certain amount from the account, decreasing the account balance, return the current account balance.
        If amount is negative, throw Exception("Invalid amount").
        If the withdrawal amount is greater than the account balance, throw Exception("Insufficient balance.").
        :param amount: Int64
        */
        if (amount < 0) {
            throw Exception("Invalid amount")
        }
        if (amount > this.balance) {
            throw Exception("Insufficient balance.")
        }
        this.balance -= amount
        return this.balance
    }

    public func view_balance(): Int64 {
        /*
        Return the account balance.
        */
        return this.balance
    }

    public func transfer(other_account: BankAccount, amount: Int64): Unit {
        /*
        Transfers a certain amount from the current account to another account.
        :param other_account: BankAccount
        :param amount: Int64
        >>> account1 = BankAccount()
        >>> account2 = BankAccount()
        >>> account1.deposit(1000)
        >>> account1.transfer(account2, 300)
        account1.balance = 700 account2.balance = 300
        */
        this.withdraw(amount)
        other_account.deposit(amount)
    }
}

import std.convert.Parsable

class BigNumCalculator {

    /*
    This is a class that implements big number calculations, including adding, subtracting and multiplying.
    */

    public static func add(num1: String, num2: String): String {
        /*
        Adds two big numbers.
        :param num1: The first number to add,String.
        :param num2: The second number to add,String.
        :return: The sum of the two numbers,String.
        >>> BigNumCalculator.add("12345678901234567890", "98765432109876543210")
        '111111111011111111100'

        */
        let max_length = max(num1.length(), num2.length())
        let padded_num1 = padLeft(num1, max_length, '0')
        let padded_num2 = padLeft(num2, max_length, '0')

        var carry = 0
        var result = ""
        let len = max_length

        for (i in (len - 1)..-1) {
            let digit1 = intFromChar(padded_num1[i])
            let digit2 = intFromChar(padded_num2[i])
            let digit_sum = digit1 + digit2 + carry
            carry = digit_sum / 10
            let digit = digit_sum % 10
            result = digit.toString() + result
        }

        if carry > 0 {
            result = carry.toString() + result
        }

        return result
    }

    public static func subtract(num1: String, num2: String): String {
        /*
        Subtracts two big numbers.
        :param num1: The first number to subtract,String.
        :param num2: The second number to subtract,String.
        :return: The difference of the two numbers,String.
        >>> BigNumCalculator.subtract("12345678901234567890", "98765432109876543210")
        '-86419753208641975320'

        */
        var n1 = num1
        var n2 = num2
        var negative = false

        if n1.length() < n2.length() {
            (n1, n2) = (n2, n1)
            negative = true
        } else if n1.length() > n2.length() {
            negative = false
        } else {
            if n1 < n2 {
                (n1, n2) = (n2, n1)
                negative = true
            } else {
                negative = false
            }
        }

        let max_length = max(n1.length(), n2.length())
        let padded_num1 = padLeft(n1, max_length, '0')
        let padded_num2 = padLeft(n2, max_length, '0')

        var borrow = 0
        var result = ""
        let len = max_length

        for (i in (len - 1)..-1) {
            let digit1 = intFromChar(padded_num1[i])
            let digit2 = intFromChar(padded_num2[i])
            var digit_diff = digit1 - digit2 - borrow

            if digit_diff < 0 {
                digit_diff += 10
                borrow = 1
            } else {
                borrow = 0
            }

            result = digit_diff.toString() + result
        }

        // Remove leading zeros
        result = removeLeadingZeros(result)

        if negative && result != "0" {
            result = "-" + result
        }

        return result
    }

    public static func multiply(num1: String, num2: String): String {
        /*
        Multiplies two big numbers.
        :param num1: The first number to multiply,String.
        :param num2: The second number to multiply,String.
        :return: The product of the two numbers,String.
        >>> BigNumCalculator.multiply("12345678901234567890", "98765432109876543210")
        '1219326311370217952237463801111263526900'

        */
        let len1 = num1.length()
        let len2 = num2.length()

        if len1 == 0 || len2 == 0 {
            return "0"
        }

        // Result can have at most len1 + len2 digits
        var result = Array<Int32>(len1 + len2, 0)

        // Multiply each digit of num1 with each digit of num2
        for (i in (len1 - 1)..-1) {
            for (j in (len2 - 1)..-1) {
                let mul = intFromChar(num1[i]) * intFromChar(num2[j])
                let p1 = i + j
                let p2 = i + j + 1
                let total = mul + result[p2]

                result[p1] += total / 10
                result[p2] = total % 10
            }
        }

        // Convert result array to string
        var product = ""
        var start = 0

        // Find the first non-zero digit
        while start < result.length() && result[start] == 0 {
            start += 1
        }

        // If all digits are zero
        if start == result.length() {
            return "0"
        }

        // Convert remaining digits to string
        for (i in start..result.length()) {
            product = product + result[i].toString()
        }

        return product
    }

    // Helper function to convert character digit to integer
    private static func intFromChar(c: Char): Int32 {
        return c.toInt32() - '0'.toInt32()
    }

    // Helper function to pad string with a character on the left
    private static func padLeft(s: String, length: Int32, padChar: Char): String {
        if s.length() >= length {
            return s
        }

        var result = ""
        let paddingSize = length - s.length()
        for (i in 0..paddingSize) {
            result = result + padChar.toString()
        }
        result = result + s
        return result
    }

    // Helper function to remove leading zeros from a string number
    private static func removeLeadingZeros(s: String): String {
        var result = s
        while result.length() > 1 && result[0] == '0' {
            result = result.substring(1)
        }
        return result
    }

    // Helper function to get max of two Int32 values
    private static func max(a: Int32, b: Int32): Int32 {
        return if (a > b) a else b
    }
}

