class ExpressionCalculator {

    /*
    This is a class in Cangjie that can perform calculations with basic arithmetic operations, including addition, subtraction, multiplication, division, and modulo.
    */

    var postfix_stack: ArrayList<String>
    var operat_priority: ArrayList<Int64>

    public init() {
        /*
        Initialize the expression calculator
        */
        postfix_stack = ArrayList<String>()
        operat_priority = ArrayList<Int64>([0, 3, 2, 1, -1, 1, 0, 2])
    }

    public func calculate(expression: String): Float64 {
        /*
        Calculate the result of the given postfix expression
        :param expression: String, the postfix expression to be calculated
        :return: Float64, the calculated result
        >>> expression_calculator = ExpressionCalculator()
        >>> expression_calculator.calculate("2 + 3 * 4")
        14.0

        */
        this.prepare(this.transform(expression))

        var result_stack: Deque<String> = ArrayDeque<String>()

        // Process each element in postfix_stack
        for (i in 0..this.postfix_stack.size()) {
            if (i < this.postfix_stack.size()) {
                var current_op: String = this.postfix_stack[i]
                if (!this.is_operator(current_op)) {
                    current_op = current_op.replace("~", "-")
                    result_stack.addLast(current_op)
                } else {
                    var second_value: String = result_stack.removeLast()
                    var first_value: String = result_stack.removeLast()

                    first_value = first_value.replace("~", "-")
                    second_value = second_value.replace("~", "-")

                    var temp_result: Decimal = this._calculate(Decimal.parse(first_value), Decimal.parse(second_value), current_op)
                    result_stack.addLast(temp_result.toString())
                }
            }
        }

        // The final result should be the only value left in the stack
        if (result_stack.size() > 0) {
            return Float64.parse(result_stack.removeFirst())
        }
        return 0.0
    }

    public func prepare(expression: String): Unit {
        /*
        Prepare the infix expression for conversion to postfix notation
        :param expression: String, the infix expression to be prepared
        >>> expression_calculator = ExpressionCalculator()
        >>> expression_calculator.prepare("2+3*4")

        expression_calculator.postfix_stack = ['2', '3', '4', '*', '+']
        */
        // Clear the postfix_stack first
        this.postfix_stack.clear()

        var op_stack: Deque<String> = ArrayDeque<String>()
        op_stack.addLast(",")

        var current_index: Int64 = 0
        var count: Int64 = 0

        for (i in 0..expression.size()) {
            var current_op: String = ""
            if (i < expression.size()) {
                current_op = expression[i].toString()
            } else {
                break
            }

            if (this.is_operator(current_op)) {
                if (count > 0) {
                    var substr: String = ""
                    for (j in current_index..(current_index + count)) {
                        if (j < expression.size()) {
                            substr = substr + expression[j].toString()
                        }
                    }
                    this.postfix_stack.addLast(substr)
                }
                var peek_op: String = op_stack.getLast()
                if (current_op == ")") {
                    while (op_stack.getLast() != "(") {
                        this.postfix_stack.addLast(op_stack.removeLast())
                    }
                    op_stack.removeLast()
                } else {
                    while (current_op != "(" && peek_op != "," && this.compare(current_op, peek_op)) {
                        this.postfix_stack.addLast(op_stack.removeLast())
                        peek_op = op_stack.getLast()
                    }
                    op_stack.addLast(current_op)
                }

                count = 0
                current_index = i + 1
            } else {
                count += 1
            }
        }

        if (count > 1 || (count == 1 && (current_index < expression.size()) && 
            !this.is_operator(expression[current_index].toString()))) {
            var substr: String = ""
            for (j in current_index..(current_index + count)) {
                if (j < expression.size()) {
                    substr = substr + expression[j].toString()
                }
            }
            this.postfix_stack.addLast(substr)
        }

        while (op_stack.getLast() != ",") {
            this.postfix_stack.addLast(op_stack.removeLast())
        }
    }

    public static func is_operator(c: String): Bool {
        /*
        Check if a character is an operator in ['+', '-', '*', '/', '(', ')', '%']
        :param c: String, the character to be checked
        :return: Bool, true if the character is an operator, false otherwise
        >>> ExpressionCalculator.is_operator("+")
        true

        */
        return (c == "+" || c == "-" || c == "*" || c == "/" || c == "(" || c == ")" || c == "%")
    }

    public func compare(cur: String, peek: String): Bool {
        /*
        Compare the precedence of two operators
        :param cur: String, the current operator
        :param peek: String, the operator at the top of the operator stack
        :return: Bool, true if the current operator has higher or equal precedence, false otherwise
        >>> expression_calculator = ExpressionCalculator()
        >>> expression_calculator.compare("+", "-")
        true

        */
        var cur_op: String = cur
        var peek_op: String = peek
        if (cur_op == "%") {
            cur_op = "/"
        }
        if (peek_op == "%") {
            peek_op = "/"
        }

        // Map operators to their priority indices based on ASCII value - 40
        var cur_priority: Int64 = this.get_priority_by_operator(cur_op)
        var peek_priority: Int64 = this.get_priority_by_operator(peek_op)

        return peek_priority >= cur_priority
    }

    private func get_priority_by_operator(op: String): Int64 {
        if (op == "(") return this.operat_priority[0]  // ASCII 40 -> index 0
        else if (op == ")") return this.operat_priority[1]  // ASCII 41 -> index 1
        else if (op == "*") return this.operat_priority[2]  // ASCII 42 -> index 2
        else if (op == "+") return this.operat_priority[3]  // ASCII 43 -> index 3
        else if (op == ",") return this.operat_priority[4]  // ASCII 44 -> index 4
        else if (op == "-") return this.operat_priority[5]  // ASCII 45 -> index 5
        else if (op == ".") return this.operat_priority[6]  // ASCII 46 -> index 6
        else if (op == "/") return this.operat_priority[7]  // ASCII 47 -> index 7
        else return -999  // for invalid operators
    }

    public static func _calculate(first_value: Decimal, second_value: Decimal, current_op: String): Decimal {
        /*
        Perform the mathematical calculation based on the given operands and operator
        :param first_value: Decimal, the first operand
        :param second_value: Decimal, the second operand
        :param current_op: String, the operator
        :return: Decimal, the calculated result
        >>> ExpressionCalculator._calculate("2", "3", "+")
        5.0

        */
        if (current_op == "+") {
            return first_value + second_value
        } else if (current_op == "-") {
            return first_value - second_value
        } else if (current_op == "*") {
            return first_value * second_value
        } else if (current_op == "/") {
            return first_value / second_value
        } else if (current_op == "%") {
            return first_value % second_value
        } else {
            throw Exception("Unexpected operator: ${current_op}")
        }
    }

    public static func transform(expression: String): String {
        /*
        Transform the infix expression to a format suitable for conversion
        :param expression: String, the infix expression to be transformed
        :return: String, the transformed expression
        >>> ExpressionCalculator.transform("2 + 3 * 4")
        "2+3*4"

        */
        var expr: String = expression
        // Remove all whitespace
        expr = Regex("\\s+").replaceAll(expr, "")
        // Remove equals sign at the end
        expr = Regex("=$").replaceAll(expr, "")

        var result: String = ""
        var prev_c: String = ""

        for (i in 0..expr.size()) {
            if (i < expr.size()) {
                var c: String = expr[i].toString()
                if (c == "-") {
                    if (i == 0 || prev_c == "+" || prev_c == "-" || prev_c == "*" || prev_c == "/" || 
                        prev_c == "(" || prev_c == "E" || prev_c == "e") {
                        result = result + "~"
                    } else {
                        result = result + c
                    }
                } else {
                    result = result + c
                }
                prev_c = c
            }
        }

        if (result.size() > 0 && result[0].toString() == "~" && 
            (result.size() > 1 && result[1].toString() == "(")) {
            // Replace the first occurrence of "~" with "-"
            var temp_result: String = ""
            var replaced: Bool = false
            for (i in 0..result.size()) {
                if (i < result.size()) {
                    var c: String = result[i].toString()
                    if (c == "~" && !replaced) {
                        temp_result = temp_result + "-"
                        replaced = true
                    } else {
                        temp_result = temp_result + c
                    }
                }
            }
            var new_result: String = "0" + temp_result
            return new_result
        } else {
            return result
        }
    }
}

import std.collection.ArrayList
import std.collection.HashMap
import std.math.abs
import std.math.pow

class FitnessTracker {

    /*
    This is a class as fitness tracker that implements to calculate BMI (Body Mass Index) and calorie intake based on the user's height, weight, age, and sex.
    */

    let height: Float64
    let weight: Float64
    let age: Int64
    let sex: String
    let BMI_std: ArrayList<HashMap<String, ArrayList<Int64>>>

    public init(height: Float64, weight: Float64, age: Int64, sex: String) {
        /*
        Initialize the class with height, weight, age, and sex, and calculate the BMI standard based on sex, and male is 20-25, female is 19-24.
        */
        this.height = height
        this.weight = weight
        this.age = age
        this.sex = sex
        this.BMI_std = ArrayList<HashMap<String, ArrayList<Int64>>>()
        this.BMI_std.add(HashMap<String, ArrayList<Int64>>([("male", ArrayList<Int64>([20, 25]))]))
        this.BMI_std.add(HashMap<String, ArrayList<Int64>>([("female", ArrayList<Int64>([19, 24]))]))
    }

    public func get_BMI(): Float64 {
        /*
        Calculate the BMI based on the height and weight.
        :return: BMI,which is the weight divide by the square of height, Float64.
        >>> fitnessTracker = FitnessTracker(1.8, 70.0, 20, "male")
        >>> fitnessTracker.get_BMI()
        21.604938271604937

        */
        return this.weight / pow(this.height, 2.0)
    }

    public func condition_judge(): Int64 {
        /*
        Judge the condition of the user based on the BMI standard.
        :return: 1 if the user is too fat, -1 if the user is too thin, 0 if the user is normal, Int64.
        >>> fitnessTracker = FitnessTracker(1.8, 70.0, 20, "male")
        >>> fitnessTracker.condition_judge()
        -1

        */
        let BMI = this.get_BMI()
        let BMI_range: ArrayList<Int64>
        if (this.sex == "male") {
            BMI_range = this.BMI_std[0]["male"]!
        } else {
            BMI_range = this.BMI_std[1]["female"]!
        }
        if (BMI > Float64(BMI_range[1])) {
            // too fat
            return 1
        } else if (BMI < Float64(BMI_range[0])) {
            // too thin
            return -1
        } else {
            // normal
            return 0
        }
    }

    public func calculate_calorie_intake(): Float64 {
        /*
        Calculate the calorie intake based on the user's condition and BMR (Basal Metabolic Rate),BMR is calculated based on the user's height, weight, age, and sex,male is Float64(10) * this.weight + 6.25 * this.height - Float64(5) * Float64(this.age) + Float64(5),female is Float64(10) * this.weight + 6.25 * this.height - Float64(5) * Float64(this.age) - Float64(161), and the calorie intake is calculated based on the BMR and the user's condition,if the user is too fat, the calorie intake is BMR * 1.2, if the user is too thin, the calorie intake is BMR * 1.6, if the user is normal, the calorie intake is BMR * 1.4.
        :return: calorie intake, Float64.
        >>> fitnessTracker = FitnessTracker(1.8, 70.0, 20, "male")
        >>> fitnessTracker.calculate_calorie_intake()
        986.0

        */
        let BMR: Float64
        if (this.sex == "male") {
            BMR = 10.0 * this.weight + 6.25 * this.height - 5.0 * Float64(this.age) + 5.0
        } else {
            BMR = 10.0 * this.weight + 6.25 * this.height - 5.0 * Float64(this.age) - 161.0
        }
        let condition = this.condition_judge()
        if (condition == 1) {
            let calorie_intake = BMR * 1.2  // Sedentary lifestyle
            return calorie_intake
        } else if (condition == -1) {
            let calorie_intake = BMR * 1.6  // Active lifestyle
            return calorie_intake
        } else {
            let calorie_intake = BMR * 1.4  // Moderate lifestyle
            return calorie_intake
        }
    }
}

import std.collection.ArrayList

class GomokuGame {

    /*
    This class is an implementation of a Gomoku game, supporting for making moves, checking for a winner, and checking if there are five consecutive symbols on the game board.
    */

    let board_size: Int64
    let board: ArrayList<ArrayList<String>>
    var current_player: String

    public init(board_size: Int64) {
        /*
        Initializes the game with a given board size.
        It initializes the board with empty spaces and sets the current player symbol as 'X'.
        */
        this.board_size = board_size
        this.board = ArrayList<ArrayList<String>>()
        this.current_player = "X"
        for (_ in 0..board_size) {
            let row: ArrayList<String> = ArrayList<String>()
            for (_ in 0..board_size) {
                row.add(" ")
            }
            board.add(row)
        }
    }

    public func make_move(row: Int64, col: Int64): Bool {
        /*
        Makes a move at the given row and column.
        If the move is valid, it places the current player's symbol on the board
        and changes the current player to the other player (if the current player is 'X', then it becomes 'O' and vice versa).
        :param row: Int64, the row index of this move
        :param col: Int64, the column index
        return: true if the move is valid, or false otherwise.
        >>> gomokuGame = GomokuGame(10)
        >>> gomokuGame.make_move(5, 5)
        true
        >>> gomokuGame.make_move(5, 5)
        false
        */
        if (this.board.get(row).get(col) == " ") {
            this.board.get(row).set(col, this.current_player)
            this.current_player = if (this.current_player == "X") "O" else "X"
            return true
        }
        return false
    }

    public func check_winner(): Option<String> {
        /*
        Checks if there is a winner by looking for five in a row in all directions (horizontal, vertical, diagonal).
        return: the symbol of the winning player (either 'X' or 'O') if there is a winner, or None otherwise.
        >>> gomokuGame = GomokuGame(10)
        >>> moves = [(5, 5), (0, 0), (5, 4), (0, 1), (5, 3), (0, 2), (5, 2), (0, 3), (5, 1)]
        >>> for (move in moves) {
        ...     gomokuGame.make_move(move[0], move[1])
        ... }
        >>> gomokuGame.check_winner()
        'X'
        */
        let directions: ArrayList<(Int64, Int64)> = ArrayList<(Int64, Int64)>()
        directions.add((0, 1))  // horizontal
        directions.add((1, 0))  // vertical
        directions.add((1, 1))  // diagonal down-right
        directions.add((1, -1)) // diagonal down-left

        for (row in 0..this.board_size) {
            for (col in 0..this.board_size) {
                let cell_value: String = this.board.get(row).get(col)
                if (cell_value != " ") {
                    for (direction in directions) {
                        if (this._check_five_in_a_row(row, col, direction)) {
                            return Option<String>.some(cell_value)
                        }
                    }
                }
            }
        }
        return Option<String>.none()
    }

    public func _check_five_in_a_row(row: Int64, col: Int64, direction: (Int64, Int64)): Bool {
        /*
        checks if there are five consecutive symbols of the same player in a row starting from a given cell in a given direction (horizontal, vertical, diagonal).
        Counts the number of consecutive symbols in that direction starting from the given cell,
        :param row: Int64, row of the given cell
        :param col: Int64, column of the given cell
        :param direction: tuple, (Int64, Int64), named as (dx, dy). Row and col will plus several dx and dy repectively.
        :return: true if there are five consecutive symbols of the same player, and false otherwise.
        >>> gomokuGame = GomokuGame(10)
        >>> moves = [(5, 5), (0, 0), (5, 4), (0, 1), (5, 3), (0, 2), (5, 2), (0, 3), (5, 1)]
        >>> for (move in moves) {
        ...     gomokuGame.make_move(move[0], move[1])
        ... }
        >>> gomokuGame._check_five_in_a_row(5, 1, (0, 1))
        true
        >>> gomokuGame._check_five_in_a_row(5, 1, (1, 1))
        false
        */
        let (dx, dy) = direction
        let symbol: String = this.board.get(row).get(col)
        var count: Int64 = 1

        for (i in 1..5) {
            let new_row: Int64 = row + dx * i
            let new_col: Int64 = col + dy * i

            if (!(0 <= new_row && new_row < this.board_size && 0 <= new_col && new_col < this.board_size)) {
                return false
            }

            if (this.board.get(new_row).get(new_col) != symbol) {
                return false
            }

            count = count + 1
        }

        return count == 5
    }
}

import std.collection.HashMap

class Hotel {

    /*
    This is a class as hotel management system, managing the booking, check-in, check-out, and availability of rooms in a hotel with different room types.
    */

    let name: String
    let available_rooms: HashMap<String, Int64>
    var booked_rooms: HashMap<String, HashMap<String, Int64>>

    public init(name: String, rooms: HashMap<String, Int64>) {
        /*
        Initialize the three fields in Hotel System.
        name is the hotel name.
        available_rooms stores the remaining rooms in the hotel
        booked_rooms stores the rooms that have been booked and the person's name who booked rooms.
        >>> hotel.name
        'peace hotel'
        >>> hotel.available_rooms
        available_rooms = {'single': 5, 'double': 3}
        >>> hotel.booked_rooms
        {'single': {'guest 1': 2, 'guest 2':1}, 'double': {'guest1': 1}}
        */
        this.name = name
        this.available_rooms = HashMap<String, Int64>(rooms)
        this.booked_rooms = HashMap<String, HashMap<String, Int64>>()
    }

    public func book_room(room_type: String, room_number: Int64, name: String): String {
        /*
        Check if there are any rooms of the specified type available.
        if rooms are adequate, modify available_rooms and booked_rooms and finish booking, or fail to book otherwise.
        :param room_type: String
        :param room_number: Int64, the expected number of specified type rooms to be booked
        :param name: String, guest name
        :return: if number of rooms about to be booked doesn't exceed the remaining rooms, return str 'Success!'
                if exceeds but quantity of available rooms is not equal to zero, return Int64.toString() (the remaining quantity of this room type).
                if exceeds and quantity is zero or the room_type isn't in available_room, return 'false'.
        >>> hotel = Hotel('peace hotel', HashMap<String, Int64>([('single', 5), ('double', 3)]))
        >>> hotel.book_room('single', 1, 'guest 1')
        'Success!'
        >>> hotel.book_room('single', 5, 'guest 1')
        '4'
        >>> hotel.book_room('single', 4, 'guest 1')
        'Success!'
        >>> hotel.book_room('single', 1, 'guest 1')
        'false'
        >>> hotel.book_room('triple', 1, 'guest 1')
        'false'
        */
        // Check if there are any rooms of the specified type available
        if !this.available_rooms.contains(room_type) {
            return "false"
        }

        let available = this.available_rooms.get(room_type)!

        if room_number <= available {
            // Book the room by adding it to the booked_rooms dictionary
            if !this.booked_rooms.contains(room_type) {
                this.booked_rooms[room_type] = HashMap<String, Int64>()
            }
            this.booked_rooms[room_type][name] = room_number
            this.available_rooms[room_type] = available - room_number
            return "Success!"
        } else if available != 0 {
            return available.toString()
        } else {
            return "false"
        }
    }

    public func check_in(room_type: String, room_number: Int64, name: String): Bool {
        /*
        Check if the room of the specified type and number is booked by the person named name.
        Remove this name when check in successfuly(room_number is equal to specific person's booked_rooms. When the actual check in quantity (room_number) is less than the booked quantity, number in booked_rooms will be booked quantity minus actual quantity
        :param room_type: String, check in room type
        :param room_number: Int64, check in room number
        :param name: String, person name
        :return false: only if the room_type is not in the booked_rooms or room_number is higher than quantity in booked rooms.
        >>> hotel = Hotel('peace hotel', HashMap<String, Int64>([('single', 5), ('double', 3)]))
        >>> hotel.book_room('single', 1, 'guest 1')
        true
        >>> hotel.check_in('single', 2, 'guest 1')
        false
        >>> hotel.check_in('single', 1, 'guest 1')
        true
        >>> hotel.booked_rooms
        {'single': {}}
        */
        // Check if the room of the specified type and number is booked
        if !this.booked_rooms.contains(room_type) {
            return false
        }
        if this.booked_rooms[room_type].contains(name) {
            let booked_number = this.booked_rooms[room_type].get(name)!
            if room_number > booked_number {
                return false
            } else if room_number == booked_number {
                // Check in the room by removing it from the booked_rooms dictionary
                this.booked_rooms[room_type].remove(name)
                return true
            } else {
                this.booked_rooms[room_type][name] = booked_number - room_number
                return true
            }
        } else {
            return false
        }
    }

    public func check_out(room_type: String, room_number: Int64): Unit {
        /*
        Check out rooms, add number for specific type in available_rooms.
        If room_type is new, add new type in available_rooms.
        :param room_type: String, check out room type
        :param room_number: Int64, check out room number
        >>> hotel = Hotel('peace hotel', HashMap<String, Int64>([('single', 5), ('double', 3)]))
        >>> hotel.check_out('single', 2)
        >>> hotel.available_rooms
        {'single': 7, 'double': 3}
        >>> hotel.check_out('triple', 2)
        >>> hotel.available_rooms
        {'single': 7, 'double': 3, 'triple': 2}
        */
        if this.available_rooms.contains(room_type) {
            this.available_rooms[room_type] += room_number
        } else {
            this.available_rooms[room_type] = room_number
        }
    }

    public func get_available_rooms(room_type: String): Int64 {
        /*
        Get the number of specific type of available rooms.
        :param room_type: String, the room type that want to know
        :return: Int64, the remaining number of this type rooms.
        >>> hotel = Hotel('peace hotel', HashMap<String, Int64>([('single', 5), ('double', 3)]))
        >>> hotel.get_available_rooms('single')
        5
        */
        return this.available_rooms.get(room_type)!
    }
}

import std.collection.HashMap
import std.collection.ArrayList

class Employee <: Equatable<Employee> {

    /*
    This is a class representing an employee with attributes such as name, position, department, and salary.
    */

    var name: String
    var position: String
    var department: String
    var salary: Int64

    public init(name: String, position: String, department: String, salary: Int64) {
        /*
        Initialize an Employee with name, position, department, and salary.
        :param name: The employee's name, String.
        :param position: The employee's position, String.
        :param department: The employee's department, String.
        :param salary: The employee's salary, Int64.
        */
        this.name = name
        this.position = position
        this.department = department
        this.salary = salary
    }

    public override operator func != (that: Employee): Bool {
        /*
        Check if two Employee objects are not equal.
        :param that: Another Employee object to compare with.
        :return: true if any attribute is different, false otherwise.
        */
        return this.name != that.name || this.position != that.position || this.department != that.department || this.salary != that.salary
    }

    public override operator func == (that: Employee): Bool {
        /*
        Check if two Employee objects are equal.
        :param that: Another Employee object to compare with.
        :return: true if all attributes are the same, false otherwise.
        */
        return this.name == that.name && this.position == that.position && this.department == that.department && this.salary == that.salary
    }
}

class HRManagementSystem {

    /*
    This is a class as personnel management system that implements functions such as adding, deleting, querying, and updating employees
    */

    var employees: HashMap<Int64, Employee>

    public init() {
        /*
        Initialize the HRManagementSystem withan attribute employees, which is an empty dictionary.
        */
        this.employees = HashMap<Int64, Employee>()
    }

    public func add_employee(employee_id: Int64, name: String, position: String, department: String, salary: Int64): Bool {
        /*
        Add a new employee to the HRManagementSystem.
        :param employee_id: The employee's id, Int64.
        :param name: The employee's name, String.
        :param position: The employee's position, String.
        :param department: The employee's department, String.
        :param salary: The employee's salary, Int64.
        :return: If the employee is already in the HRManagementSystem, returns false, otherwise, returns true.
        >>> hrManagementSystem = HRManagementSystem()
        >>> hrManagementSystem.add_employee(1, 'John', 'Manager', 'Sales', 100000)
        true
        >>> hrManagementSystem.add_employee(1, 'John', 'Manager', 'Sales', 100000)
        false

        */
        if (this.employees.contains(employee_id)) {
            return false
        } else {
            var employee: Employee = Employee(name, position, department, salary)
            this.employees.add(employee_id, employee)
            return true
        }
    }

    public func remove_employee(employee_id: Int64): Bool {
        /*
        Remove an employee from the HRManagementSystem.
        :param employee_id: The employee's id, Int64.
        :return: If the employee is already in the HRManagementSystem, returns true, otherwise, returns false.
        >>> hrManagementSystem = HRManagementSystem()
        >>> hrManagementSystem.employees.add(1, Employee('John', 'Manager', 'Sales', 100000))
        >>> hrManagementSystem.remove_employee(1)
        true
        >>> hrManagementSystem.remove_employee(2)
        false

        */
        if (this.employees.contains(employee_id)) {
            this.employees.remove(employee_id)
            return true
        } else {
            return false
        }
    }

    public func update_employee(employee_id: Int64, employee_info: HashMap<String, Any>): Bool {
        /*
        Update an employee's information in the HRManagementSystem.
        :param employee_id: The employee's id, Int64.
        :param employee_info: The employee's information, HashMap<String, Any>.
        :return: If the employee is already in the HRManagementSystem, returns true, otherwise, returns false.
        >>> hrManagementSystem = HRManagementSystem()
        >>> hrManagementSystem.employees.add(1, Employee('John', 'Manager', 'Sales', 100000))
        >>> hrManagementSystem.update_employee(1, HashMap<String, Any>([('name', 'John Doe'), ('position', 'Manager'), ('department', 'Sales'), ('salary', 20000)]))
        true
        >>> hrManagementSystem.update_employee(2, HashMap<String, Any>([('name', 'John Doe'), ('position', 'Manager'), ('department', 'Sales'), ('salary', 20000)]))
        false

        */
        var employee_option = this.employees.get(employee_id)
        if (employee_option.isEmpty()) {
            return false
        } else {
            var employee = employee_option.getOrThrow()

            // Check if all keys in employee_info are valid
            var iter = employee_info.entries()
            while (iter.hasNext()) {
                var entry = iter.next()
                var key = entry.key
                if (key != "name" && key != "position" && key != "department" && key != "salary") {
                    return false
                }
            }

            // Update the employee information
            var info_iter = employee_info.entries()
            while (info_iter.hasNext()) {
                var entry = info_iter.next()
                var key = entry.key
                var value = entry.value
                if (key == "name") {
                    employee.name = value as! String
                } else if (key == "position") {
                    employee.position = value as! String
                } else if (key == "department") {
                    employee.department = value as! String
                } else if (key == "salary") {
                    employee.salary = value as! Int64
                }
            }
            return true
        }
    }

    public func get_employee(employee_id: Int64): Option<Employee> {
        /*
        Get an employee's information from the HRManagementSystem.
        :param employee_id: The employee's id, Int64.
        :return: If the employee is already in the HRManagementSystem, returns the employee's information, otherwise, returns None.
        >>> hrManagementSystem = HRManagementSystem()
        >>> hrManagementSystem.employees.add(1, Employee('John', 'Manager', 'Sales', 100000))
        >>> hrManagementSystem.get_employee(1)
        Employee('John', 'Manager', 'Sales', 100000)
        >>> hrManagementSystem.get_employee(2)
        None

        */
        return this.employees.get(employee_id)
    }

    public func list_employees(): ArrayList<Employee> {
        /*
        List all employees' information in the HRManagementSystem.
        :return: A list of all employees' information, ArrayList<Employee>.
        >>> hrManagementSystem = HRManagementSystem()
        >>> hrManagementSystem.employees = HashMap<Int64, Employee>([(1, Employee('John', 'Manager', 'Sales', 100000))])
        >>> hrManagementSystem.list_employees()
        ArrayList<Employee>([Employee('John', 'Manager', 'Sales', 100000)])

        */
        var employee_list: ArrayList<Employee> = ArrayList<Employee>()
        var iter = this.employees.values()
        while (iter.hasNext()) {
            var employee = iter.next()
            employee_list.add(employee)
        }
        return employee_list
    }
}

import std.collection.ArrayList

class Interpolation {

    /*
    This is a class that implements the Linear interpolation operation of one-dimensional and two-dimensional data
    */

    public static func interpolate_1d(x: ArrayList<Float64>, y: ArrayList<Float64>, x_interp: ArrayList<Float64>): ArrayList<Float64> {
        /*
        Linear interpolation of one-dimensional data
        :param x: The x-coordinate of the data point, ArrayList<Float64>.
        :param y: The y-coordinate of the data point, ArrayList<Float64>.
        :param x_interp: The x-coordinate of the interpolation point, ArrayList<Float64>.
        :return: The y-coordinate of the interpolation point, ArrayList<Float64>.
        >>> Interpolation.interpolate_1d(ArrayList<Float64>([1.0, 2.0, 3.0]), ArrayList<Float64>([1.0, 2.0, 3.0]), ArrayList<Float64>([1.5, 2.5]))
        [1.5, 2.5]

        */
        var y_interp: ArrayList<Float64> = ArrayList<Float64>()
        for (xi in x_interp) {
            for (i in 0..x.size - 1) {
                if (i + 1 < x.size && x[i] <= xi && xi <= x[i + 1]) {
                    var yi: Float64 = y[i] + (y[i + 1] - y[i]) * (xi - x[i]) / (x[i + 1] - x[i])
                    y_interp.add(yi)
                    break
                }
            }
        }
        return y_interp
    }

    public static func interpolate_2d(x: ArrayList<Float64>, y: ArrayList<Float64>, z: ArrayList<ArrayList<Float64>>, x_interp: ArrayList<Float64>, y_interp: ArrayList<Float64>): ArrayList<Float64> {
        /*
        Linear interpolation of two-dimensional data
        :param x: The x-coordinate of the data point, ArrayList<Float64>.
        :param y: The y-coordinate of the data point, ArrayList<Float64>.
        :param z: The z-coordinate of the data point, ArrayList<ArrayList<Float64>>.
        :param x_interp: The x-coordinate of the interpolation point, ArrayList<Float64>.
        :param y_interp: The y-coordinate of the interpolation point, ArrayList<Float64>.
        :return: The z-coordinate of the interpolation point, ArrayList<Float64>.
        >>> let x = ArrayList<Float64>([1.0, 2.0, 3.0])
        >>> let y = ArrayList<Float64>([1.0, 2.0, 3.0])
        >>> let z = ArrayList<ArrayList<Float64>>([ArrayList<Float64>([1.0, 2.0, 3.0]), ArrayList<Float64>([4.0, 5.0, 6.0]), ArrayList<Float64>([7.0, 8.0, 9.0])])
        >>> let x_interp = ArrayList<Float64>([1.5, 2.5])
        >>> let y_interp = ArrayList<Float64>([1.5, 2.5])
        >>> let result = Interpolation.interpolate_2d(x, y, z, x_interp, y_interp)
        >>> result
        [3.0, 7.0]

        */
        var z_interp: ArrayList<Float64> = ArrayList<Float64>()
        var interp_idx: Int64 = 0
        for (xi in x_interp) {
            var yi: Float64 = y_interp[interp_idx]
            for (i in 0..x.size - 1) {
                if (i + 1 < x.size && x[i] <= xi && xi <= x[i + 1]) {
                    for (j in 0..y.size - 1) {
                        if (j + 1 < y.size && y[j] <= yi && yi <= y[j + 1]) {
                            var z00: Float64 = z[i][j]
                            var z01: Float64 = z[i][j + 1]
                            var z10: Float64 = z[i + 1][j]
                            var z11: Float64 = z[i + 1][j + 1]
                            var zi: Float64 = (z00 * (x[i + 1] - xi) * (y[j + 1] - yi) +
                                              z10 * (xi - x[i]) * (y[j + 1] - yi) +
                                              z01 * (x[i + 1] - xi) * (yi - y[j]) +
                                              z11 * (xi - x[i]) * (yi - y[j])) / ((x[i + 1] - x[i]) * (y[j + 1] - y[j]))
                            z_interp.add(zi)
                            break
                        }
                    }
                    break
                }
            }
            interp_idx = interp_idx + 1
        }
        return z_interp
    }
}

import std.convert.Parsable
import std.convert.Formattable
import std.collection.ArrayList

class IPAddress {

    /*
    This is a class to process IP Address, including validating, getting the octets and obtaining the binary representation of a valid IP address.
    */

    let ip_address: String

    public init(ip_address: String) {
        /*
        Initialize the IP address to the specified address
        :param ip_address:String
        */
        this.ip_address = ip_address
    }

    public func is_valid(): Bool {
        /*
        Judge whether the IP address is valid, that is, whether the IP address is composed of four Decimal digits separated by '.'. Each digit is greater than or equal to 0 and less than or equal to 255
        :return: Bool
        >>> ipaddress = IPAddress("10.10.10.10")
        >>> ipaddress.is_valid()
        true
        */
        var octets = this.ip_address.split(".", false)
        if (octets.length != 4) {
            return false
        }
        for (i in 0..4) {
            var octet = octets[i]
            if (!octet.chars().allMatch({ c => c.isDigit() })) {
                return false
            }
            var num = Int32.parse(octet)
            if (num < 0 || num > 255) {
                return false
            }
        }
        return true
    }

    public func get_octets(): ArrayList<String> {
        /*
        If the IP address is valid, the list of four decimal numbers separated by "." constituting the IP address is returned; otherwise, an empty list is returned
        :return: ArrayList<String>
        >>> ipaddress = IPAddress("10.10.10.10")
        >>> ipaddress.get_octets()
        ["10", "10", "10", "10"]
        */
        if (this.is_valid()) {
            var octets = this.ip_address.split(".", false)
            var result = ArrayList<String>(4)
            for (i in 0..octets.length) {
                result.add(octets[i])
            }
            return result
        } else {
            return ArrayList<String>()
        }
    }

    public func get_binary(): String {
        /*
        If the IP address is valid, return the binary form of the IP address; otherwise, return ''
        :return: String
        >>> ipaddress = IPAddress("10.10.10.10")
        >>> ipaddress.get_binary()
        "00001010.00001010.00001010.00001010"
        */
        if (this.is_valid()) {
            var octets = this.get_octets()
            var binary_octets = ArrayList<String>(4)
            for (i in 0..octets.length) {
                var octet = Int32.parse(octets[i])
                var binary = ""
                var temp = octet
                // Convert to binary with 8 bits
                for (j in 0..8) {
                    if ((temp & (1 << (7 - j))) != 0) {
                        binary = binary + "1"
                    } else {
                        binary = binary + "0"
                    }
                }
                binary_octets.add(binary)
            }
            var result = ""
            for (i in 0..binary_octets.length) {
                if (i == 0) {
                    result = binary_octets[i]
                } else {
                    result = result + "." + binary_octets[i]
                }
            }
            return result
        } else {
            return ""
        }
    }
}

import std.net.IPAddress
import std.posix.gethostname

class IpUtil {

    /*
    This is a class as tool for ip that can be used to obtain the local IP address, validate its validity, and also provides the functionality to retrieve the corresponding hostname.
    */

    public static func is_valid_ipv4(ip_address: String): Bool {
        /*
        Check if the given IP address is a valid IPv4 address.
        :param ip_address: String, the IP address to check
        :return: Bool, true if the IP address is valid, false otherwise
        >>> IpUtil.is_valid_ipv4('192.168.0.123')
        true
        >>> IpUtil.is_valid_ipv4('256.0.0.0')
        false

        */
        let ip = IPAddress.tryParse(ip_address)
        if (ip == None) {
            return false
        }
        return ip.value.isIPv4()
    }

    public static func is_valid_ipv6(ip_address: String): Bool {
        /*
        Check if the given IP address is a valid IPv6 address.
        :param ip_address:String, the IP address to check
        :return:Bool, true if the IP address is valid, false otherwise
        >>> IpUtil.is_valid_ipv6('2001:0db8:85a3:0000:0000:8a2e:0370:7334')
        true
        >>> IpUtil.is_valid_ipv6('2001:0db8:85a3:::8a2e:0370:7334')
        false

        */
        let ip = IPAddress.tryParse(ip_address)
        if (ip == None) {
            return false
        }
        return ip.value.isIPv6()
    }

    public static func get_hostname(ip_address: String): Option<String> {
        /*
        Get the hostname associated with the given IP address.
        :param ip_address:String, the IP address to get the hostname for
        :return: String, the hostname associated with the IP address
        >>> IpUtil.get_hostname('110.242.68.3')
        'www.baidu.com'
        >>> IpUtil.get_hostname('10.0.0.1')
        None

        */
        let ip = IPAddress.tryParse(ip_address)
        if (ip == None) {
            return None
        }
        return ip.value.hostName
    }
}

import std.collection.ArrayList

class Resume <: Equatable<Resume> {

    /*
    Represents a candidate's resume containing personal information, skills, and work experience.
    This class is used within the job marketplace system to store and manage applicant data.
    It conforms to the Equatable interface to allow comparison between resume instances.
    */

    let name: String
    let skills: ArrayList<String>
    let experience: String

    public init(name: String, skills: ArrayList<String>, experience: String) {
        this.name = name
        this.skills = skills
        this.experience = experience
    }

    public override operator func != (that: Resume): Bool {
        return this.name != that.name || this.skills != that.skills || this.experience != that.experience
    }

    public override operator func == (that: Resume): Bool {
        return this.name == that.name && this.skills == that.skills && this.experience == that.experience
    }
}

class JobListing <: Equatable<JobListing> {

    /*
