class Stock <: Equatable<Stock> {

    let name: String
    var price: Float64
    var quantity: Int64

    public init(name: String, price: Float64, quantity: Int64) {
        this.name = name
        this.price = price
        this.quantity = quantity
    }

    public override operator func != (that: Stock): Bool {
        return this.name != that.name || this.price != that.price || this.quantity != that.quantity
    }

    public override operator func == (that: Stock): Bool {
        return this.name == that.name && this.price == that.price && this.quantity == that.quantity
    }
}

class StockPortfolioTracker {

    /*
    This is a class as StockPortfolioTracker that allows to add stocks, remove stocks, buy stocks, sell stocks, calculate the total value of the portfolio, and obtain a summary of the portfolio.
    */

    var portfolio: ArrayList<Stock>
    var cash_balance: Float64

    public init(cash_balance: Float64) {
        /*
        Initialize the StockPortfolioTracker class with a cash balance and an empty portfolio.
        */
        this.portfolio = ArrayList<Stock>()
        this.cash_balance = cash_balance
    }

    public func add_stock(stock: Stock): Unit {
        /*
        Add a stock to the portfolio.
        :param stock: Stock
        >>> tracker = StockPortfolioTracker(10000.0)
        >>> tracker.add_stock(Stock("AAPL", 150.0, 10))
        >>> tracker.portfolio
        [Stock("AAPL", 150.0, 10)]

        */
        for (var i: Int64 = 0; i < this.portfolio.size; i += 1) {
            var pf: Stock = this.portfolio.get(i).getOrThrow()
            if (pf.name == stock.name) {
                pf.quantity += stock.quantity
                return
            }
        }
        this.portfolio.add(stock)
    }

    public func remove_stock(stock: Stock): Bool {
        /*
        Remove a stock from the portfolio.
        :param stock: Stock
        >>> tracker = StockPortfolioTracker(10000.0)
        >>> tracker.portfolio = [Stock("AAPL", 150.0, 10)]
        >>> tracker.remove_stock(Stock("AAPL", 150.0, 10))
        true
        >>> tracker.portfolio
        []

        */
        for (var i: Int64 = 0; i < this.portfolio.size; i += 1) {
            var pf: Stock = this.portfolio.get(i).getOrThrow()
            if (pf.name == stock.name && pf.quantity >= stock.quantity) {
                pf.quantity -= stock.quantity
                if (pf.quantity == 0) {
                    this.portfolio.remove(at: i)
                }
                return true
            }
        }
        return false
    }

    public func buy_stock(stock: Stock): Bool {
        /*
        Buy a stock and add it to the portfolio.
        :param stock: Stock
        :return: true if the stock was bought successfully, false if the cash balance is not enough.
        >>> tracker = StockPortfolioTracker(10000.0)
        >>> tracker.buy_stock(Stock("AAPL", 150.0, 10))
        true
        >>> tracker.portfolio
        [Stock("AAPL", 150.0, 10)]

        */
        if (stock.price * Float64.fromInt64(stock.quantity) > this.cash_balance) {
            return false
        } else {
            this.add_stock(stock: stock)
            this.cash_balance -= stock.price * Float64.fromInt64(stock.quantity)
            return true
        }
    }

    public func sell_stock(stock: Stock): Bool {
        /*
        Sell a stock and remove it from the portfolio and add the cash to the cash balance.
        :param stock: Stock
        :return: true if the stock was sold successfully, false if the quantity of the stock is not enough.
        >>> tracker = StockPortfolioTracker(10000.0)
        >>> tracker.portfolio = [Stock("AAPL", 150.0, 10)]
        >>> tracker.sell_stock(Stock("AAPL", 150.0, 10))
        true
        >>> tracker.portfolio
        []

        */
        if (this.remove_stock(stock: stock) == false) {
            return false
        }
        this.cash_balance += stock.price * Float64.fromInt64(stock.quantity)
        return true
    }

    public func calculate_portfolio_value(): Float64 {
        /*
        Calculate the total value of the portfolio.
        :return: the total value of the portfolio, Float64.
        >>> tracker = StockPortfolioTracker(10000.0)
        >>> tracker.portfolio = [Stock("AAPL", 150.0, 10)]
        >>> tracker.calculate_portfolio_value()
        11500.0

        */
        var total_value: Float64 = this.cash_balance
        for (var i: Int64 = 0; i < this.portfolio.size; i += 1) {
            var stock: Stock = this.portfolio.get(i).getOrThrow()
            total_value += stock.price * Float64.fromInt64(stock.quantity)
        }
        return total_value
    }

    public func get_portfolio_summary(): (Float64, ArrayList<HashMap<String, Any>>) {
        /*
        Get a summary of the portfolio.
        :return: a tuple of the total value of the portfolio and a list of dictionaries with keys "name" and "value"
        >>> tracker = StockPortfolioTracker(10000.0)
        >>> tracker.portfolio = [Stock("AAPL", 150.0, 10)]
        >>> tracker.get_portfolio_summary()
        (11500.0, [{'name': 'AAPL', 'value': 1500.0}])

        */
        var summary: ArrayList<HashMap<String, Any>> = ArrayList<HashMap<String, Any>>()
        for (var i: Int64 = 0; i < this.portfolio.size; i += 1) {
            var stock: Stock = this.portfolio.get(i).getOrThrow()
            var stock_map: HashMap<String, Any> = HashMap<String, Any>()
            stock_map.add("name", stock.name)
            stock_map.add("value", this.get_stock_value(stock: stock))
            summary.add(stock_map)
        }
        var portfolio_value: Float64 = this.calculate_portfolio_value()
        return (portfolio_value, summary)
    }

    public func get_stock_value(stock: Stock): Float64 {
        /*
        Get the value of a stock.
        :param stock: Stock
        :return: the value of the stock, Float64.
        >>> tracker = StockPortfolioTracker(10000.0)
        >>> tracker.get_stock_value(Stock("AAPL", 150.0, 10))
        1500.0

        */
        return stock.price * Float64.fromInt64(stock.quantity)
    }
}

import std.math.abs

class Thermostat {

    /*
    The class manages temperature control, including setting and retrieving the target temperature, adjusting the mode, and simulating temperature operation.
    */

    var current_temperature: Float64
    var target_temperature: Float64
    var mode: String

    public init(current_temperature: Float64, target_temperature: Float64, mode: String) {
        /*
        initialize instances of the Thermostat class, including the current temperature, target temperature, and operating mode.
        :param current_temperature: Float64
        :param target_temperature: Float64
        :param mode: String, the work mode
        */
        this.current_temperature = current_temperature
        this.target_temperature = target_temperature
        this.mode = mode
    }

    public func get_target_temperature(): Float64 {
        /*
        Get the target temperature of an instance of the Thermostat class.
        :return this.target_temperature: Float64
        >>> thermostat.get_target_temperature()
        37.5
        */
        return this.target_temperature
    }

    public func set_target_temperature(temperature: Float64): Unit {
        /*
        Set the target temperature
        :param temperature: Float64, the target temperature
        >>> thermostat.set_target_temperature(37.6)
        >>> thermostat.target_temperature
        37.6
        */
        this.target_temperature = temperature
    }

    public func get_mode(): String {
        /*
        Get the current work mode
        :return mode: String, working mode. only ['heat', 'cool']
        */
        return this.mode
    }

    public func set_mode(mode: String): Bool {
        /*
        Get the current work mode
        :param mode: String, working mode. only ['heat', 'cool']
        >>> thermostat.set_mode('cool')
        >>> thermostat.mode
        'cool'
        */
        if mode == "heat" || mode == "cool" {
            this.mode = mode
            return true
        } else {
            return false
        }
    }

    public func auto_set_mode(): Unit {
        /*
        Automatically set the operating mode by comparing with the current temperature and target temperature. If the current temperature is lower than the target temperature, the operating mode is set to 'heat', otherwise it is set to 'cool'.
        >>> thermostat = Thermostat(20.4, 37.5, 'cool')
        >>> thermostat.auto_set_mode()
        >>> thermostat.mode
        'heat'
        */
        if this.current_temperature < this.target_temperature {
            this.mode = "heat"
        } else {
            this.mode = "cool"
        }
    }

    public func auto_check_conflict(): Bool {
        /*
        Check if there is a conflict between the operating mode and the relationship between the current temperature and the target temperature.
        If there is a conflict, the operating mode will be adjusted automatically.
        :return: true if mode isn't conflict with the relationship between the current temperature and the target temperature, or false otherwise.
        >>> thermostat = Thermostat(20.4, 37.5, 'cool')
        >>> thermostat.auto_check_conflict()
        false
        >>> thermostat.mode
        'heat'
        */
        if this.current_temperature > this.target_temperature {
            if this.mode == "cool" {
                return true
            } else {
                this.auto_set_mode()
                return false
            }
        } else {
            if this.mode == "heat" {
                return true
            } else {
                this.auto_set_mode()
                return false
            }
        }
    }

    public func simulate_operation(): Int64 {
        /*
        simulate the operation of Thermostat. It will automatically start the auto_set_mode method to set the operating mode,
        and then automatically adjust the current temperature according to the operating mode until the target temperature is reached.
        :return time: Int64, the time it took to complete the simulation.
        >>> thermostat = Thermostat(20.4, 37.5, 'cool')
        >>> thermostat.simulate_operation()
        18
        */
        this.auto_set_mode()
        var use_time: Int64 = 0
        if this.mode == "heat" {
            while this.current_temperature < this.target_temperature {
                this.current_temperature += 1.0
                use_time += 1
            }
        } else {
            while this.current_temperature > this.target_temperature {
                this.current_temperature -= 1.0
                use_time += 1
            }
        }
        return use_time
    }
}

import std.collection.ArrayList

class TicTacToe {

    /*
    The class represents a game of Tic-Tac-Toe and its functions include making a move on the board, checking for a winner, and determining if the board is full.
    */

    let board: ArrayList<ArrayList<String>>
    var current_player: String

    public init(N!: Int64 = 3) {
        /*
        Initialize a 3x3 game board with all empty spaces and current symble player, default is 'X'.
        */
        this.board = ArrayList<ArrayList<String>>()
        for (_ in 0..3) {
            let row = ArrayList<String>()
            for (_ in 0..N) {
                row.add(" ")
            }
            this.board.add(row)
        }
        this.current_player = "X"
    }

    public func make_move(row: Int64, col: Int64): Bool {
        /*
        Place the current player's mark at the specified position on the board and switch the mark.
        :param row: Int64, the row index of the position
        :param col: Int64, the column index of the position
        :return: Bool, indicating whether the move was successful or not
        >>> ttt.current_player
        'X'
        >>> ttt.make_move(1, 1)
        >>> ttt.current_player
        'O'
        */
        if (this.board.get(row).get(col) == " ") {
            this.board[row][col] = this.current_player
            this.current_player = if (this.current_player == "X") "O" else "X"
            return true
        } else {
            return false
        }
    }

    public func check_winner(): Option<String> {
        /*
        Check if there is a winner on the board in rows, columns and diagonals three directions
        :return: Option<String>, the mark of the winner ('X' or 'O'), or None if there is no winner yet
        >>> moves = ArrayList<ArrayList<Int64>>([ArrayList<Int64>([1, 0]), ArrayList<Int64>([2, 0]), ArrayList<Int64>([1, 1]), ArrayList<Int64>([2, 1]), ArrayList<Int64>([1, 2])])
        >>> for move in moves:
        ...     ttt.make_move(move[0], move[1])
        >>> ttt.check_winner()
        'X'
        */
        // Check rows
        for (row in 0..3) {
            if (this.board[row][0] == this.board[row][1] && this.board[row][1] == this.board[row][2] && this.board[row][0] != " ") {
                return Some(this.board[row][0])
            }
        }

        // Check columns
        for (col in 0..3) {
            if (this.board[0][col] == this.board[1][col] && this.board[1][col] == this.board[2][col] && this.board[0][col] != " ") {
                return Some(this.board[0][col])
            }
        }

        // Check diagonals
        if (this.board[0][0] == this.board[1][1] && this.board[1][1] == this.board[2][2] && this.board[0][0] != " ") {
            return Some(this.board[0][0])
        }
        if (this.board[0][2] == this.board[1][1] && this.board[1][1] == this.board[2][0] && this.board[0][2] != " ") {
            return Some(this.board[0][2])
        }

        return None
    }

    public func is_board_full(): Bool {
        /*
        Check if the game board is completely filled.
        :return: Bool, indicating whether the game board is full or not
        >>> ttt.is_board_full()
        false
        */
        for (row in 0..3) {
            for (col in 0..3) {
                if (this.board[row][col] == " ") {
                    return false
                }
            }
        }
        return true
    }
}

import std.time.DateTime
import std.math.round
import std.core.*
import std.time.*

class TimeUtils {

    /*
    This is a time util class, including getting the current time and date, adding seconds to a datetime, converting between strings and datetime objects, calculating the time difference in minutes, and formatting a datetime object.
    */

    let datetime: DateTime

    public init() {
        /*
        Get the current datetime
        */
        this.datetime = DateTime.now()
    }

    public func get_current_time(): String {
        /*
        Return the current time in the format of 'HH:mm:ss'
        :return: String
        >>> timeutils = TimeUtils()
        >>> timeutils.get_current_time()
        "19:19:22"
        */
        return this.datetime.format("HH:mm:ss")
    }

    public func get_current_date(): String {
        /*
        Return the current date in the format of "yyyy-MM-dd"
        :return: String
        >>> timeutils.get_current_date()
        "2023-06-14"
        */
        return this.datetime.format("yyyy-MM-dd")
    }

    public func add_seconds(seconds: Int64): String {
        /*
        Add the specified number of seconds to the current time
        :param seconds: Int64, number of seconds to add
        :return: String, time after adding the specified number of seconds in the format 'HH:mm:ss'
        >>> timeutils.add_seconds(600)
        "19:29:22"
        */
        let new_datetime = this.datetime.addSeconds(seconds)
        return new_datetime.format("HH:mm:ss")
    }

    public func string_to_datetime(string: String): DateTime {
        /*
        Convert the time string to a datetime instance
        :param string: String, string before converting format
        :return: DateTime
        >>> timeutils.string_to_datetime("2001-07-18 01:01:01")
        2001-07-18 01:01:01
        */
        return DateTime.parse(string, "yyyy-MM-dd HH:mm:ss")
    }

    public func datetime_to_string(datetime: DateTime): String {
        /*
        Convert a datetime instance to a string
        :param datetime: the DatetTime instance to convert
        :return: String, converted time string
        >>> timeutils.datetime_to_string(timeutils.datetime)
        "2023-06-14 19:30:03"
        */
        return datetime.format("yyyy-MM-dd HH:mm:ss")
    }

    public func get_minutes(string_time1: String, string_time2: String): Int64 {
        /*
        Calculate how many minutes have passed between two times, and round the results to the nearest
        :return: Int64, the number of minutes between two times, rounded off
        >>> timeutils.get_minutes("2001-07-18 01:01:01", "2001-07-18 02:01:01")
        60
        */
        let time1 = this.string_to_datetime(string_time1)
        let time2 = this.string_to_datetime(string_time2)
        let duration = time2 - time1
        let seconds = duration.toSeconds()
        let minutes = seconds / 60
        return round(Float64(minutes))
    }

    public func get_format_time(year: Int64, month: Int64, day: Int64, hour: Int64, minute: Int64, second: Int64): String {
        /*
        get format time
        :param year: Int64
        :param month: Int64
        :param day: Int64
        :param hour: Int64
        :param minute: Int64
        :param second: Int64
        :return: formatted time string
        >>> timeutils.get_format_time(2001, 7, 18, 1, 1, 1)
        "2001-07-18 01:01:01"
        */
        let datetime = DateTime.of(year: year, month: month, dayOfMonth: day, hour: hour, minute: minute, second: second)
        return datetime.format("yyyy-MM-dd HH:mm:ss")
    }
}

import std.math.numeric.Decimal
import std.math.numeric.round
import std.math.abs
import std.math.FloatingPoint

class TriCalculator {

    /*
    The class allows to calculate trigonometric values, including cosine, sine, and tangent, using Taylor series approximations.
    */

    public init() {}

    public func cos(x: Float64): Float64 {
        /*
        Calculate the cos value of the x-degree angle
        :param x:Float64
        :return:Float64
        >>> tricalculator = TriCalculator()
        >>> tricalculator.cos(60.0)
        0.5
        */
        return self.roundToDecimalPlaces(self.taylor(x, 50), 10)
    }

    public func factorial(a: Int64): Decimal {
        /*
        Calculate the factorial of a
        :param a: Int64
        :return: Decimal
        >>> tricalculator.factorial(5)
        Decimal(120)
        */
        var b: Decimal = Decimal(1)
        var tempA = a
        while tempA != 1 {
            b = b * Decimal(tempA)
            tempA = tempA - 1
        }
        return b
    }

    public func taylor(x: Float64, n: Int64): Float64 {
        /*
        Finding the n-order Taylor expansion value of cos (x/180 * pi)
        :param x: Float64
        :param n: Int64
        :return: Float64
        >>> tricalculator.taylor(60.0, 50)
        0.5000000000000001
        */
        var a: Float64 = 1.0
        let xRad = x / 180.0 * Float64.getPI()
        var count: Int64 = 1
        var k: Int64 = 1
        while k < n {
            if count % 2 != 0 {
                let numerator = self.power(xRad, 2 * k)
                let denominator = self.factorialInt(2 * k)
                a = a - (numerator / Float64(denominator))
            } else {
                let numerator = self.power(xRad, 2 * k)
                let denominator = self.factorialInt(2 * k)
                a = a + (numerator / Float64(denominator))
            }
            count = count + 1
            k = k + 1
        }
        return a
    }

    private func power(x: Float64, n: Int64): Float64 {
        var result: Float64 = 1.0
        var i: Int64 = 0
        while i < n {
            result = result * x
            i = i + 1
        }
        return result
    }

    private func factorialInt(n: Int64): Int64 {
        var result: Int64 = 1
        var tempN = n
        while tempN != 1 {
            result = result * tempN
            tempN = tempN - 1
        }
        return result
    }

    private func roundToDecimalPlaces(value: Float64, places: Int64): Float64 {
        let multiplier = self.power(10.0, places)
        let temp = value * multiplier
        let rounded = self.roundToNearest(temp)
        return rounded / multiplier
    }

    private func roundToNearest(value: Float64): Float64 {
        if value >= 0.0 {
            let truncated = Float64(Int64(value))
            if value - truncated >= 0.5 {
                return truncated + 1.0
            } else {
                return truncated
            }
        } else {
            let truncated = Float64(Int64(value))
            if abs(value - truncated) >= 0.5 {
                return truncated - 1.0
            } else {
                return truncated
            }
        }
    }

    public func sin(x: Float64): Float64 {
        /*
        Calculate the sin value of the x-degree angle
        :param x: Float64
        :return: Float64
        >>> tricalculator.sin(30.0)
        0.5
        */
        let xRad = x / 180.0 * Float64.getPI()
        var g: Float64 = 0.0
        var t: Float64 = xRad
        var n: Int64 = 1

        while abs(t) >= 1e-15 {
            g = g + t
            n = n + 1
            t = -t * xRad * xRad / Float64(2 * n - 1) / Float64(2 * n - 2)
        }
        return self.roundToDecimalPlaces(g, 10)
    }

    public func tan(x: Float64): Option<Float64> {
        /*
        Calculate the tan value of the x-degree angle
        If abs(this.cos(x) - 0.0) > 0.000001, return None
        :param x: Float64
        :return: Option<Float64>
        >>> tricalculator.tan(45.0)
        1.0
        */
        let cosValue = self.cos(x)
        if abs(cosValue) > 1e-6 {
            let result = self.sin(x) / cosValue
            return Option.Some(self.roundToDecimalPlaces(result, 10))
        } else {
            return Option.None()
        }
    }
}

import std.collection.ArrayList
import std.collection.HashMap
import std.random.Random
import std.convert.Parsable

class Parser {

    /*
    This class is used to parse the expression to get the answer
    params: expression, String
    >>> parser = Parser("4+3+6+6")
    >>> parser.parse()
    19
    */

    let expr: String
    var pos: Int64
    var ch: Rune

    public init(expr: String) {
        this.expr = expr
        this.pos = -1
        this.ch = r'x'
        this.next_char()
    }

    public func next_char(): Unit {
        this.pos += 1
        if (this.pos < this.expr.size) {
            this.ch = Rune(this.expr[this.pos])
        } else {
            this.ch = r'x'
        }
    }

    public func eat(char_to_eat: Rune): Bool {
        while (this.ch == r' ') {
            this.next_char()
        }
        if (this.ch == char_to_eat) {
            this.next_char()
            return true
        }
        return false
    }

    public func parse(): Int64 {
        let x = this.parse_expression()
        if (this.pos < this.expr.size) {
            throw Exception("Unexpected: ${this.ch}")
        }
        return x
    }

    public func parse_expression(): Int64 {
        var x = this.parse_term()
        while (true) {
            if (this.eat(r'+')) {
                x += this.parse_term()
            } else if (this.eat(r'-')) {
                x -= this.parse_term()
            } else {
                return x
            }
        }
        return x
    }

    public func parse_term(): Int64 {
        var x = this.parse_factor()
        while (true) {
            if (this.eat(r'*')) {
                x *= this.parse_factor()
            } else if (this.eat(r'/')) {
                x /= this.parse_factor()
            } else {
                return x
            }
        }
        return x
    }

    public func parse_factor(): Int64 {
        if (this.eat(r'+')) {
            return this.parse_factor()
        }
        if (this.eat(r'-')) {
            return -this.parse_factor()
        }

        var x = 0
        var start_pos = this.pos

        if (this.eat(r'(')) {
            x = this.parse_expression()
            this.eat(r')')
        } else if (this.ch != r'x' && (this.ch.isAsciiNumber() || this.ch == r'.')) {
            while (this.ch != r'x' && (this.ch.isAsciiNumber() || this.ch == r'.')) {
                this.next_char()
            }
            x = Int64.parse(this.expr[start_pos..this.pos])
        } else {
            if (this.ch != r'x') {
                throw Exception("Unexpected: ${this.ch}")
            } else {
                throw Exception("Unexpected end of expression")
            }
        }
        return x
    }
}

class TwentyFourPointGame {

    /*
    This ia a game of twenty-four points, which provides to generate four numbers and check whether player's expression is equal to 24.
    */

    var nums: ArrayList<Int64>

    public init() {
        this.nums = ArrayList<Int64>()
    }

    public func _generate_cards(): Unit {
        /*
        Generate random numbers between 1 and 9 for the cards.
        */
        let random = Random()
        this.nums.clear()
        for (let i: Int64 = 0; i < 4; i += 1) {
            this.nums.add(random.nextInt64(1, 10))  // 1 to 9
        }
    }

    public func get_my_cards(): ArrayList<Int64> {
        /*
        Get a list of four random numbers between 1 and 9 representing the player's cards.
        :return: ArrayList<Int64>, representing the player's cards
        >>> game = TwentyFourPointGame()
        >>> game.get_my_cards()

        */
        this.nums.clear()
        this._generate_cards()
        return this.nums
    }

    public func answer(expression: String): Bool {
        /*
        Check if a given mathematical expression using the cards can evaluate to 24.
        :param expression: String, mathematical expression using the cards
        :return: Bool, true if the expression evaluates to 24, false otherwise
        >>> game = TwentyFourPointGame()
        >>> game.nums = [4, 3, 6, 6]
        >>> ans = "4*3+6+6"
        >>> ret = game.answer(ans)
        true
        */
        if (expression == "pass") {
            return this.get_my_cards().size > 0  // Return true if new cards were generated
        }

        var statistic = HashMap<Int64, Int64>()
        for (let c: Rune in expression) {
            if (c.isAsciiNumber()) {
                let digit = Int64.parse(String(c))
                if (this.nums.contains(digit)) {
                    let count = statistic.get(digit) ?? 0
                    statistic[digit] = count + 1
                }
            }
        }

        var nums_used = HashMap<Int64, Int64>()
        for (let entry: (Int64, Int64) in statistic) {
            nums_used[entry.0] = entry.1
        }

        for (let num: Int64 in this.nums) {
            let count = nums_used.get(num) ?? -100
            if (count != -100 && count > 0) {
                nums_used[num] -= 1
            } else {
                return false
            }
        }

        var all_zero = true
        for (let count: Int64 in nums_used.values()) {
            if (count != 0) {
                all_zero = false
                break
            }
        }

        if (all_zero) {
            return this.evaluate_expression(expression)
        } else {
            return false
        }
    }

    public func evaluate_expression(expression: String): Bool {
        /*
        Evaluate a mathematical expression and check if the result is 24.
        :param expression: String, mathematical expression
        :return: Bool, true if the expression evaluates to 24, false otherwise
        >>> game = TwentyFourPointGame()
        >>> nums = [4, 3, 6, 6]
        >>> ans = "4*3+6+6"
        >>> ret = game.evaluate_expression(ans)
        true
        */
        try {
            let parser = Parser(expression)
            let result = parser.parse()
            return result == 24
        } catch (e: Exception) {
            return false
        }
    }
}

import std.collection.HashMap

class URLHandler {

    /*
    The class supports to handle URLs, including extracting the scheme, host, path, query parameters, and fragment.
    */

    let url: String

    public init(url: String) {
        /*
        Initialize URLHandler's URL
        */
        this.url = url
    }

    public func get_scheme(): Option<String> {
        /*
        get the scheme of the URL
        :return: Option<String>, If successful, return the scheme of the URL
        >>> urlhandler = URLHandler("https://www.baidu.com/s?wd=aaa&rsv_spt=1#page")
        >>> urlhandler.get_scheme()
        "https"
        */
        let scheme_end = this.url.indexOf("://")
        match (scheme_end) {
            case Some(pos) => return Some(this.url[0..pos])
            case None => return None
        }
    }

    public func get_host(): Option<String> {
        /*
        Get the second part of the URL, which is the host domain name
        :return: Option<String>, If successful, return the host domain name of the URL
        >>> urlhandler = URLHandler("https://www.baidu.com/s?wd=aaa&rsv_spt=1#page")
        >>> urlhandler.get_host()
        "www.baidu.com"
        */
        let scheme_end = this.url.indexOf("://")
        match (scheme_end) {
            case Some(pos) => {
                let url_without_scheme = this.url[(pos + 3)..this.url.size]
                let host_end = url_without_scheme.indexOf("/")
                match (host_end) {
                    case Some(host_pos) => return Some(url_without_scheme[0..host_pos])
                    case None => return Some(url_without_scheme)
                }
            }
            case None => return None
        }
    }

    public func get_path(): Option<String> {
        /*
        Get the third part of the URL, which is the address of the resource
        :return: Option<String>, If successful, return the address of the resource of the URL
        >>> urlhandler = URLHandler("https://www.baidu.com/s?wd=aaa&rsv_spt=1#page")
        >>> urlhandler.get_path()
        "/s?wd=aaa&rsv_spt=1#page"
        */
        let scheme_end = this.url.indexOf("://")
        match (scheme_end) {
            case Some(pos) => {
                let url_without_scheme = this.url[(pos + 3)..this.url.size]
                let host_end = url_without_scheme.indexOf("/")
                match (host_end) {
                    case Some(host_pos) => return Some(url_without_scheme[host_pos..url_without_scheme.size])
                    case None => return None
                }
            }
            case None => return None
        }
    }

    public func get_query_params(): Option<HashMap<String, String>> {
        /*
        Get the request parameters for the URL
        :return: Option<HashMap<String, String>>, If successful, return the request parameters of the URL
        >>> urlhandler = URLHandler("https://www.baidu.com/s?wd=aaa&rsv_spt=1#page")
        >>> urlhandler.get_query_params()
        {"wd": "aaa", "rsv_spt": "1"}
        */
        let query_start = this.url.indexOf("?")
        let fragment_start = this.url.indexOf("#")
        match (query_start) {
            case Some(pos) => {
                let end_pos: Int64 = match (fragment_start) {
                    case Some(frag_pos) => frag_pos
                    case None => this.url.size
                }
                let query_string = this.url[(pos + 1)..end_pos]
                let params = HashMap<String, String>()
                let len = query_string.size
                if (len > 0) {
                    let pairs = query_string.split("&")
                    for (pair in pairs) {
                        let key_value = pair.split("=", maxSplits: 2)
                        if (key_value.size == 2) {
                            let key = key_value[0]
                            let value = key_value[1]
                            params[key] = value
                        }
                    }
                }
                return Some(params)
            }
            case None => return None
        }
    }

    public func get_fragment(): Option<String> {
        /*
        Get the fragment after '#' in the URL
        :return: Option<String>, If successful, return the fragment after '#' of the URL
        >>> urlhandler = URLHandler("https://www.baidu.com/s?wd=aaa&rsv_spt=1#page")
        >>> urlhandler.get_fragment()
        "page"
        */
        let fragment_start = this.url.indexOf("#")
        match (fragment_start) {
            case Some(pos) => return Some(this.url[(pos + 1)..this.url.size])
            case None => return None
        }
    }
}

import std.collection.ArrayList

class UrlPath {

    /*
    The  class is a utility for encapsulating and manipulating the path component of a URL, including adding nodes, parsing path strings, and building path strings with optional encoding.
    */

    let segments: ArrayList<String>
    var with_end_tag: Bool

    public init() {
        /*
        Initializes the UrlPath object with an empty list of segments and a flag indicating the presence of an end tag.
        */
        this.segments = ArrayList<String>()
        this.with_end_tag = false
    }

    public func add(segment: String): Unit {
        /*
        Adds a segment to the list of segments in the UrlPath.
        :param segment: String, the segment to add.
        >>> url_path = UrlPath()
        >>> url_path.add('foo')
        >>> url_path.add('bar')

        url_path.segments = ['foo', 'bar']
        */
        this.segments.add(this.fix_path(segment))
    }

    public func parse(path: String): Unit {
        /*
        Parses a given path string and populates the list of segments in the UrlPath.
        :param path: String, the path string to parse.
        >>> url_path = UrlPath()
        >>> url_path.parse('/foo/bar/')

        url_path.segments = ['foo', 'bar']
        */
        if (!path.isEmpty()) {
            if (path.endsWith("/")) {
                this.with_end_tag = true
            }

            let fixedPath = this.fix_path(path)
            if (!fixedPath.isEmpty()) {
                let split = fixedPath.split("/")
                for (seg in split) {
                    // Since there's no direct equivalent to urllib.parse.unquote in the docs
                    // I'll assume we just use the segment as is, or implement basic URL decoding
                    let decoded_seg = this.url_decode(seg)
                    this.segments.add(decoded_seg)
                }
            }
        }
    }

    public static func fix_path(path: String): String {
        /*
        Fixes the given path string by removing leading and trailing slashes.
        :param path: String, the path string to fix.
        :return: String, the fixed path string.
        >>> url_path = UrlPath()
        >>> url_path.fix_path('/foo/bar/')
        'foo/bar'

        */
        if (path.isEmpty()) {
            return ""
        }

        let segment_str = path.trimStart("/").trimEnd("/")
        return segment_str
    }

    // Helper method to implement basic URL decoding
    private func url_decode(encoded_str: String): String {
        // Replace %XX with the corresponding character
        var result = encoded_str
        var i = 0
        while (i < result.size) {
            if (result[i] == 37) { // 37 is the ASCII code for '%'
                if (i + 2 < result.size) {
                    let hex_str = result[i+1..i+3]
                    // Convert hex string to integer
                    let hex_val = this.hex_to_int(hex_str)
                    if (hex_val >= 0) {
                        // Replace %XX with the character
                        let before = result[0..i]
                        let after = result[i+3..result.size]
                        let char = String([hex_val as Rune])
                        result = before + char + after
                        i += 1  // Move past the replaced character
                    } else {
                        i += 1
                    }
                } else {
                    i += 1
                }
            } else {
                i += 1
            }
        }
        return result
    }

    // Helper method to convert hex string to integer
    private func hex_to_int(hex_str: String): Int64 {
        if (hex_str.size != 2) {
            return -1
        }

        let hex_chars = "0123456789ABCDEF"
        let c1 = hex_str[0]
        let c2 = hex_str[1]

        var val1 = -1
        var val2 = -1

        for (i in 0..hex_chars.size) {
            if (hex_chars[i] == c1) {
                val1 = i
                break
            }
        }

        for (i in 0..hex_chars.size) {
            if (hex_chars[i] == c2) {
                val2 = i
                break
            }
        }

        if (val1 >= 0 && val2 >= 0) {
            return val1 * 16 + val2
        }

        return -1
    }
}

import std.collection.HashMap
import std.collection.ArrayList
import std.math.abs
import std.math.sqrt
import std.math.log
import std.math.pow

class VectorUtil {

    /*
    The class provides vector operations, including calculating similarity, cosine similarities, average similarity, and IDF weights.
    */

    public static func similarity(vector_1: ArrayList<Float64>, vector_2: ArrayList<Float64>): Float64 {
        /*
        Compute the cosine similarity between one vector and another vector.
        :param vector_1: ArrayList<Float64>, Vector from which similarities are to be computed, expected shape (dim,).
        :param vector_2: ArrayList<Float64>, Vector from which similarities are to be computed, expected shape (dim,).
        :return: Float64, Contains cosine distance between `vector_1` and `vector_2`
        >>> vector_1 = ArrayList<Float64>([1.0, 1.0])
        >>> vector_2 = ArrayList<Float64>([1.0, 0.0])
        >>> VectorUtil.similarity(vector_1, vector_2)
        0.7071067811865475
        */

        // Calculate dot product
        var dot_product: Float64 = 0.0
        let size = min(vector_1.size(), vector_2.size())
        for (i in 0..size) {
            dot_product += vector_1.get(i)! * vector_2.get(i)!
        }

        // Calculate norms
        var norm1: Float64 = 0.0
        var norm2: Float64 = 0.0

        for (i in 0..vector_1.size()) {
            norm1 += vector_1.get(i)! * vector_1.get(i)!
        }

        for (i in 0..vector_2.size()) {
            norm2 += vector_2.get(i)! * vector_2.get(i)!
        }

        norm1 = sqrt(norm1)
        norm2 = sqrt(norm2)

        // Return cosine similarity
        if (norm1 == 0.0 || norm2 == 0.0) {
            return 0.0
        }
        return dot_product / (norm1 * norm2)
    }

    public static func cosine_similarities(vector_1: ArrayList<Float64>, vectors_all: ArrayList<ArrayList<Float64>>): ArrayList<Float64> {
        /*
        Compute cosine similarities between one vector and a set of other vectors.
        :param vector_1: ArrayList<Float64>, Vector from which similarities are to be computed, expected shape (dim,).
        :param vectors_all: ArrayList<ArrayList<Float64>>, For each row in vectors_all, distance from vector_1 is computed, expected shape (num_vectors, dim).
        :return: ArrayList<Float64>, Contains cosine distance between `vector_1` and each row in `vectors_all`, shape (num_vectors,).
        >>> vector1 = ArrayList<Float64>([1.0, 2.0, 3.0])
        >>> vectors_all = ArrayList<ArrayList<Float64>>([ArrayList<Float64>([4.0, 5.0, 6.0]), ArrayList<Float64>([7.0, 8.0, 9.0])])
        >>> VectorUtil.cosine_similarities(vector1, vectors_all)
        [0.97463185 0.95941195]
        */

        // Calculate norm of vector_1
        var norm1: Float64 = 0.0
        for (i in 0..vector_1.size()) {
            norm1 += vector_1.get(i)! * vector_1.get(i)!
        }
        norm1 = sqrt(norm1)

        let similarities = ArrayList<Float64>()

        for (vector in vectors_all) {
            // Calculate norm of current vector
            var norm2: Float64 = 0.0
            var dot_product: Float64 = 0.0

            let size = min(vector_1.size(), vector.size())
            for (i in 0..size) {
                dot_product += vector_1.get(i)! * vector.get(i)!
            }

            for (i in 0..vector.size()) {
                norm2 += vector.get(i)! * vector.get(i)!
            }
            norm2 = sqrt(norm2)

            // Calculate similarity
            var similarity: Float64 = 0.0
            if (norm1 != 0.0 && norm2 != 0.0) {
                similarity = dot_product / (norm1 * norm2)
            }

            similarities.add(similarity)
        }

        return similarities
    }

    public static func n_similarity(vector_list_1: ArrayList<ArrayList<Float64>>, vector_list_2: ArrayList<ArrayList<Float64>>): Float64 {
        /*
        Compute cosine similarity between two sets of vectors.
        :param vector_list_1: ArrayList<ArrayList<Float64>>
        :param vector_list_2: ArrayList<ArrayList<Float64>>
        :return: Float64, Similarities between vector_list_1 and vector_list_2.
        >>> vector_list1 = ArrayList<ArrayList<Float64>>([ArrayList<Float64>([1.0, 2.0, 3.0]), ArrayList<Float64>([4.0, 5.0, 6.0])])
        >>> vector_list2 = ArrayList<ArrayList<Float64>>([ArrayList<Float64>([7.0, 8.0, 9.0]), ArrayList<Float64>([10.0, 11.0, 12.0])])
        >>> VectorUtil.n_similarity(vector_list1, vector_list2)
        0.9897287473881233
        */

        if (vector_list_1.isEmpty() || vector_list_2.isEmpty()) {
            throw ZeroDivisionException("At least one of the passed list is empty.")
        }

        // Calculate mean of vector_list_1
        let first_vector = vector_list_1.get(0)!
        var mean1 = ArrayList<Float64>()
        for (i in 0..first_vector.size()) {
            mean1.add(0.0)
        }

        for (vector in vector_list_1) {
            for (i in 0..vector.size()) {
                if (i < mean1.size()) {
                    mean1.set(i, mean1.get(i)! + vector.get(i)!)
                }
            }
        }

        for (i in 0..mean1.size()) {
            mean1.set(i, mean1.get(i)! / vector_list_1.size().toFloat64())
        }

        // Calculate mean of vector_list_2
        let first_vector2 = vector_list_2.get(0)!
        var mean2 = ArrayList<Float64>()
        for (i in 0..first_vector2.size()) {
            mean2.add(0.0)
        }

        for (vector in vector_list_2) {
            for (i in 0..vector.size()) {
                if (i < mean2.size()) {
                    mean2.set(i, mean2.get(i)! + vector.get(i)!)
                }
            }
        }

        for (i in 0..mean2.size()) {
            mean2.set(i, mean2.get(i)! / vector_list_2.size().toFloat64())
        }

        // Calculate similarity between the two mean vectors
        return similarity(mean1, mean2)
    }

    public static func compute_idf_weight_dict(total_num: Int64, number_dict: HashMap<String, Float64>): HashMap<String, Float64> {
        /*
        Calculate log(total_num+1/count+1) for each count in number_dict
        :param total_num: Int64
        :param number_dict: HashMap<String, Float64>
        :return: HashMap<String, Float64>
        >>> num_dict = HashMap<String, Float64>([('key1', 0.1), ('key2', 0.5)])
        >>> VectorUtil.compute_idf_weight_dict(2, num_dict)
        {'key1': 1.0033021088637848, 'key2': 0.6931471805599453}
        */

        let index_2_key_map = HashMap<Int64, String>()
        let count_list = ArrayList<Float64>()

        var index: Int64 = 0
        let keys = ArrayList<String>()
        for (entry in number_dict) {
            keys.add(entry.0)
        }

        for (key in keys) {
            index_2_key_map.set(index, key)
            count_list.add(number_dict.get(key)!)
            index += 1
        }

        let result = HashMap<String, Float64>()

        for (i in 0..count_list.size()) {
            let count = count_list.get(i)!
            let w = log((total_num + 1).toFloat64() / (count + 1))
            let key = index_2_key_map.get(i)!
            result.set(key, w)
        }

        return result
    }
}

